import {jest} from '@jest/globals';
import Ajv from 'ajv';
import {ToolRegistry} from './registry.js';
import type {ToolExecutor} from './registry.js';

const registerWeatherTool = (
  registry: ToolRegistry,
  inputSchema: Record<string, unknown>,
  execute: ToolExecutor
): void => {
  registry.register({name: 'weather', description: 'Get weather', inputSchema}, execute);
};

describe('ToolRegistry', () => {
  it('returns a required-property rejection without invoking the tool', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'sunny');
    registerWeatherTool(
      registry,
      {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      execute
    );

    const response = await registry.execute('weather', {});
    const calls = execute.mock.calls;

    expect({
      namesRequiredField: /location.*required|required.*location/i.test(response.result),
      executorCalls: calls.length,
    }).toEqual({namesRequiredField: true, executorCalls: 0});
  });

  // @spec specs/hal-engine-tool-input-validation/spec.md#3
  it('passes valid input with extra properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', unit: 'celsius'};
    const execute = jest.fn(async (received: Record<string, unknown>) => JSON.stringify(received));
    registerWeatherTool(
      registry,
      {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      execute
    );

    await registry.execute('weather', input);

    expect(execute.mock.calls).toEqual([[input, undefined]]);
  });

  // @spec specs/hal-engine-tool-input-validation/spec.md#9
  it('validates function-valued tools against the schema resolved on each call', async () => {
    const registry = new ToolRegistry();
    let schemaCall = 0;
    const execute = jest.fn(async () => 'ok');
    registry.register(
      () => ({
        name: 'changing',
        description: 'A tool with a changing schema',
        inputSchema:
          schemaCall++ === 0
            ? {type: 'object', properties: {registered: {type: 'boolean'}}, required: ['registered']}
            : schemaCall === 2
              ? {type: 'object', properties: {first: {type: 'string'}}, required: ['first']}
              : {type: 'object', properties: {second: {type: 'number'}}, required: ['second']},
      }),
      execute
    );

    const first = await registry.execute('changing', {first: 'one'});
    const second = await registry.execute('changing', {second: 2});

    expect({first, second, calls: execute.mock.calls.length}).toEqual({
      first: {result: 'ok'},
      second: {result: 'ok'},
      calls: 2,
    });
  });

  it('static schemas compile once across repeated executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {type: 'object'},
      },
      async () => 'sunny'
    );

    await Promise.all(Array.from({length: 10}, () => registry.execute('weather', {})));

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });

  // @spec specs/hal-engine-tool-input-validation/spec.md#2
  it('names the full nested property path when a value has the wrong type', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'sunny');
    registerWeatherTool(
      registry,
      {type: 'object', properties: {place: {type: 'object', properties: {city: {type: 'string'}}}}},
      execute
    );

    const response = await registry.execute('weather', {place: {city: 123456789}});
    const calls = execute.mock.calls;

    expect({
      namesNestedField: response.result.includes('place.city'),
      namesExpectedType: response.result.includes('string'),
      omitsValue: !response.result.includes('123456789'),
      executorCalls: calls.length,
    }).toEqual({namesNestedField: true, namesExpectedType: true, omitsValue: true, executorCalls: 0});
  });

  // @spec specs/hal-engine-tool-input-validation/spec.md#4
  it('names the property and enum constraint when input is outside an enum', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'sunny');
    registerWeatherTool(
      registry,
      {type: 'object', properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}}},
      execute
    );

    const response = await registry.execute('weather', {unit: 'kelvin'});

    expect({
      namesProperty: response.result.includes('unit'),
      namesConstraint: response.result.includes('enum'),
    }).toEqual({
      namesProperty: true,
      namesConstraint: true,
    });
  });
